/** @param {{des: object}} api */
export default function bigrm_10({ des, selection, percent, math, luaList, luaLen }) {
    des.level_init({ style: 'solidfill', fg: ' ' });
    des.level_flags('mazelevel', 'noflip');

    des.map(`.......................................................................
.......................................................................
.......................................................................
.......................................................................
...C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C...
...CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC...
...C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C...
...CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC...
...C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C...
...CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC...
...C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C...
...CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC...
...C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C...
...CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC...
...C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C C...
.......................................................................
.......................................................................
.......................................................................
.......................................................................
`);

    if (percent(40)) {
        // occasionally it's not a fog maze
        // luaList keeps Lua's 1-based indices, so terrain[n] means the same here.
        const terrain = luaList('L', '}', 'T', '-', 'F');
        const tidx = math.random(1, luaLen(terrain));
        // break it up a bit
        des.replace_terrain({ region: [0, 0, 70, 18], fromterrain: 'C', toterrain: '.', chance: 5 });
        des.replace_terrain({ region: [0, 0, 70, 18], fromterrain: 'C', toterrain: terrain[tidx] });
    }

    des.region(selection.area(0, 0, 70, 18), 'lit');

    // when falling down on this level, never end up in the fog maze
    des.teleport_region({ region: [0, 0, 70, 18], exclude: [2, 3, 68, 15], dir: 'down' });

    for (let i = 1; i <= 15; i++) {
        des.object();
    }

    for (let i = 1; i <= 6; i++) {
        des.trap();
    }

    for (let i = 1; i <= 28; i++) {
        des.monster();
    }

    des.mazewalk({ x: 4, y: 2, dir: 'south', stocked: 0 });

    // Stairs up, not in the fog maze
    des.levregion({ region: [0, 0, 70, 18], exclude: [2, 3, 68, 15], type: 'stair-up' });
    des.stair('down');
}
